/* Mobile view adjustments — collection pages */
@media (max-width: 767px) {
    /* Hide the collection title on mobile — the active pill already shows the name */
    .collection-hero {
        display: none !important;
    }

    /* Small gap between search bar and pills */
    .page-width--collection-breadcrumbs {
        margin-top: 0;
        padding-top: 10px;
    }
}
